// 2. Helper Global de Debounce
window.debounce = function debounce(func, wait = 250) {
    let timeout;
    return function(...args) {
        const context = this;
        clearTimeout(timeout);
        timeout = setTimeout(() => func.apply(context, args), wait);
    };
};
