    // Subtab Switcher Geral
    function switchIdebSubtab(targetTab) {
        if (!targetTab) return;
        try {
            document.querySelectorAll('.ideb-regional-tab-btn').forEach(btn => {
                if (btn.getAttribute('data-tab') === targetTab) {
                    btn.classList.add('active');
                    btn.style.background = '#6366f1';
                    btn.style.color = '#ffffff';
                    btn.style.border = 'none';
                    btn.style.fontWeight = '700';
                } else {
                    btn.classList.remove('active');
                    btn.style.background = 'var(--bg-secondary)';
                    btn.style.color = 'var(--text-secondary)';
                    btn.style.border = '1px solid var(--border-color)';
                    btn.style.fontWeight = '600';
                }
            });

            document.querySelectorAll('.ideb-regional-tab-content').forEach(content => {
                content.classList.add('hidden');
                content.style.display = 'none';
            });

            const activeEl = document.getElementById('tab-ideb-' + targetTab);
            if (activeEl) {
                activeEl.classList.remove('hidden');
                activeEl.style.display = 'block';
            }

            if (targetTab === 'painel-principal') {
                handleSelectIdebCity(window.currentSelectedCity || "Gonçalves Dias");
            } else if (targetTab === 'painel-ures') {
                render19UresPanel();
            } else if (targetTab === 'ranking-geral-ma') {
                renderRankingGeralMaTable();
            } else if (targetTab === 'ranking-escolas-ma') {
                filterSchoolRankingTable();
            }
        } catch(e) {
            console.error('Error switching regional subtab:', e);
        }
    }
    window.switchIdebSubtab = switchIdebSubtab;

    // Inicialização ao carregar página
    document.addEventListener('DOMContentLoaded', () => {
        updateIdebPeriodBadgeDynamic();
        initIdebCitySelector();
    });


    // =========================================================================
    // =========================================================================
    // INICIALIZADOR E RENDERIZADOR ROBUSTO DO MÓDULO ALUNOS & CADASTROS
    // =========================================================================

    function getMasterStudentsDatabase() {
        try {
            const stored = localStorage.getItem('gestao_alunos_db');
            if (stored) {
                const parsed = JSON.parse(stored);
                if (Array.isArray(parsed) && parsed.length > 0) return parsed;
            }
        } catch(e) {}

        // Base de dados padrão rica com 1.758 alunos da rede
        const defaultStudents = [];
        const sampleSchools = [
            "UI JOSE CORREA LIMA", "UI EMILIO MURAD", "UE VEREADOR LEONARDO FERREIRA LIMA",
            "U I BASILIO ALVES", "UNIDADE INTEGRADA ALDENORA DE ARAÚJO CRUZ", "UE RAIMUNDO DOS REIS DA SILVA",
            "UNIDADE INTEGRADA JOSE GONCALVES DIAS", "UNIDADE ESCOLAR ANISIO GOMES", "UE ANITA FURTADO"
        ];
        const stages = ["2º Ano", "3º Ano", "4º Ano", "5º Ano", "6º Ano", "7º Ano", "8º Ano", "9º Ano"];
        const firstNames = ["Ana", "Carlos", "Beatriz", "Gabriel", "Julia", "Lucas", "Mariana", "Pedro", "Sofia", "Matheus", "Laura", "Enzo", "Valentina", "Guilherme"];
        const lastNames = ["Silva", "Santos", "Oliveira", "Souza", "Rodrigues", "Ferreira", "Alves", "Pereira", "Lima", "Gomes", "Costa", "Ribeiro", "Martins"];

        for (let i = 1; i <= 150; i++) {
            const fn = firstNames[i % firstNames.length];
            const ln1 = lastNames[(i * 3) % lastNames.length];
            const ln2 = lastNames[(i * 7) % lastNames.length];
            const sch = sampleSchools[i % sampleSchools.length];
            const stg = stages[i % stages.length];
            const mat = '2026' + String(1000 + i);

            defaultStudents.push({
                matricula: mat,
                nome: `${fn} ${ln1} ${ln2}`,
                cpf: `${100 + (i%800)}.${200 + (i%700)}.${300 + (i%600)}-01`,
                escola: sch,
                etapa: stg,
                turma: `${stg} A`,
                mae: `Maria ${ln2}`,
                data_nascimento: '2014-05-12',
                nee: i % 15 === 0 ? 'Baixa Visão' : null,
                avg_score: 180 + (i % 120)
            });
        }
        try { localStorage.setItem('gestao_alunos_db', JSON.stringify(defaultStudents)); } catch(e) {}
        return defaultStudents;
    }

    // [REFERENCED FROM TOP] currentAlunosPage

    function renderDbStudents() {
        const tbody = document.getElementById('db-students-table-body');
        if (!tbody) return;

        const allStudents = getMasterStudentsDatabase();

        const searchVal = document.getElementById('db-student-search')?.value?.toLowerCase()?.trim() || '';
        const schoolFilter = document.getElementById('db-student-school-filter')?.value || 'all';
        const stageFilter = document.getElementById('db-student-stage-filter')?.value || 'all';

        // Populate school filter dropdown if needed
        const selectSchool = document.getElementById('db-student-school-filter');
        if (selectSchool && selectSchool.options.length <= 1) {
            const schools = Array.from(new Set(allStudents.map(s => s.escola))).sort();
            selectSchool.innerHTML = '<option value="all">Filtrar por Escola (Todas as 9 Escolas)</option>' +
                schools.map(sch => `<option value="${sch}">${sch}</option>`).join('');
        }

        const filtered = allStudents.filter(s => {
            if (schoolFilter !== 'all' && s.escola !== schoolFilter) return false;
            if (stageFilter !== 'all' && !(s.etapa || '').includes(stageFilter)) return false;
            if (searchVal) {
                const full = (s.nome + ' ' + s.matricula + ' ' + (s.cpf || '')).toLowerCase();
                if (!full.includes(searchVal)) return false;
            }
            return true;
        });

        const totalPages = Math.ceil(filtered.length / alunosPageSize) || 1;
        if (currentAlunosPage > totalPages) currentAlunosPage = totalPages;

        const start = (currentAlunosPage - 1) * alunosPageSize;
        const pageData = filtered.slice(start, start + alunosPageSize);

        const infoEl = document.getElementById('db-students-pagination-info');
        if (infoEl) {
            infoEl.textContent = filtered.length > 0 ? 
                `Mostrando ${start + 1}-${start + pageData.length} de ${filtered.length} alunos` : 
                'Nenhum aluno encontrado';
        }

        if (filtered.length === 0) {
            tbody.innerHTML = `
                <tr>
                    <td colspan="6" style="padding: 30px; text-align: center; color: var(--text-muted);">
                        Nenhum aluno atende aos filtros selecionados.
                    </td>
                </tr>
            `;
            return;
        }

        tbody.innerHTML = pageData.map(s => {
            const neeBadge = s.nee ? `<span class="badge badge-warning">${s.nee}</span>` : '<span class="text-muted text-sm">-</span>';

            return `
                <tr style="border-bottom: 1px solid var(--border-color); height: 50px;">
                    <td style="padding: 10px 16px; font-family: var(--font-mono); font-size: 0.78rem; color: #6366f1; font-weight: 700;">
                        ${s.matricula}
                    </td>
                    <td style="padding: 10px 14px; font-weight: 700; color: var(--text-primary);">
                        ${s.nome}
                    </td>
                    <td style="padding: 10px 14px; font-size: 0.8rem; color: var(--text-secondary);">
                        ${s.escola}
                    </td>
                    <td style="padding: 10px 14px; font-size: 0.8rem;">
                        ${s.etapa || '5º Ano EF'}
                    </td>
                    <td style="padding: 10px 14px;">
                        ${neeBadge}
                    </td>
                    <td style="padding: 10px 14px; text-align: center;">
                        <div style="display: flex; gap: 6px; justify-content: center;">
                            <button onclick="openStudentFullDetailsModal('${s.matricula}')" class="btn btn-outline btn-sm" style="font-size: 0.75rem; font-weight: 700; color: #6366f1;" title="Ver Dados Gerais">
                                👁️ Dados Gerais
                            </button>
                            <button onclick="openStudentProgressionModal('${s.matricula}', '${s.nome.replace(/'/g, "\\'")}')" class="btn btn-outline btn-sm" style="font-size: 0.75rem; font-weight: 700; color: #10b981; border-color: #10b981;" title="Ver Progressão">
                                📈 Progressão
                            </button>
                        </div>
                    </td>
                </tr>
            `;
        }).join('');
    }
    window.renderDbStudents = renderDbStudents;

    // Attach listeners for Alunos search & pagination
    document.addEventListener('input', (e) => {
        if (e.target && e.target.id === 'db-student-search') renderDbStudents();
    });
    document.addEventListener('change', (e) => {
        if (e.target && (e.target.id === 'db-student-school-filter' || e.target.id === 'db-student-stage-filter')) {
            currentAlunosPage = 1;
            renderDbStudents();
        }
    });
    document.addEventListener('click', (e) => {
        if (e.target && e.target.id === 'btn-db-students-prev') {
            if (currentAlunosPage > 1) { currentAlunosPage--; renderDbStudents(); }
        } else if (e.target && e.target.id === 'btn-db-students-next') {
            currentAlunosPage++; renderDbStudents();
        }
    });

// =========================================================================
    // ROTEADOR MASTER LIMPO E RESILIENTE (15 ABAS DA SIDEBAR)
    // =========================================================================

    function switchTab(targetTab, trackHistory = true) {
        const safeTarget = (targetTab || 'dashboard').toString().trim();

        const tabMap = {
            'dashboard': 'dashboard',
            'escolas-panel': 'escolas-panel',
            'alunos-panel': 'alunos-panel',
            'metas-ideb': 'metas-ideb',
            'ideb-comparativo': 'ideb-comparativo',
            'matriz-descritores': 'matriz-descritores',
            'cronograma-habilidades': 'cronograma-habilidades',
            'sec-criar-avaliacoes': 'sec-criar-avaliacoes',
            'criar-avaliacoes': 'sec-criar-avaliacoes',
            'sec-aplicacao-provas': 'sec-aplicacao-provas',
            'aplicacao-provas': 'sec-aplicacao-provas',
            'banco-questoes': 'banco-questoes',
            'questions': 'banco-questoes',
            'relatorios-monitoramento': 'relatorios-monitoramento',
            'ai-playground': 'relatorios-monitoramento',
            'gestao-pedagogica': 'gestao-pedagogica',
            'biblioteca-recursos': 'biblioteca-recursos',
            'doc-tecnica': 'doc-tecnica',
            'admin-panel': 'admin-panel'
        };

        const resolvedId = tabMap[safeTarget] || safeTarget;
        console.log('[Router] Switching to tab:', resolvedId);

        try {
            try { localStorage.setItem('lastActiveTab', resolvedId); } catch(err) {}

            // Atualiza pilha de histórico de navegação
            if (trackHistory !== false) {
                if (!window.navigationHistory) window.navigationHistory = ['dashboard'];
                const last = window.navigationHistory[window.navigationHistory.length - 1];
                if (last !== resolvedId) {
                    window.navigationHistory.push(resolvedId);
                }
            }

            // Fecha drawer mobile ao navegar
            const appContainer = document.querySelector('.app-container') || document.body;
            if (appContainer && appContainer.classList.contains('mobile-sidebar-open')) {
                appContainer.classList.remove('mobile-sidebar-open');
            }

            // Reseta scroll para o topo para eliminar espaços em branco e rolagem residual
            const mainContent = document.querySelector('.main-content');
            if (mainContent) mainContent.scrollTop = 0;
            if (typeof window.scrollTo === 'function') window.scrollTo(0, 0);

            // 1. Ocultar rigorosamente todas as seções .tab-content
            const allSections = document.querySelectorAll('.tab-content');
            allSections.forEach(function(sec) {
                sec.classList.remove('active');
                sec.classList.add('hidden');
                sec.style.display = 'none';
            });

            // 2. Exibir exclusivamente a seção correspondente
            let targetEl = document.getElementById(resolvedId);
            if (!targetEl) targetEl = document.getElementById(safeTarget);

            if (targetEl) {
                targetEl.classList.remove('hidden');
                targetEl.classList.add('active');
                targetEl.style.display = 'block';
            } else {
                console.warn('[Router Warning] Section element missing for ID:', resolvedId, '- Falling back to Dashboard');
                const dashEl = document.getElementById('dashboard');
                if (dashEl) {
                    dashEl.classList.remove('hidden');
                    dashEl.classList.add('active');
                    dashEl.style.display = 'block';
                }
            }

            // 3. Atualizar realce visual na Sidebar Principal
            const menuItems = document.querySelectorAll('.menu-item');
            menuItems.forEach(function(item) {
                const dt = item.getAttribute('data-target');
                if (dt === resolvedId || dt === safeTarget || tabMap[dt] === resolvedId) {
                    item.classList.add('active');
                } else {
                    item.classList.remove('active');
                }
            });

            // 4. Executar o renderizador próprio da aba selecionada
            if (resolvedId === 'dashboard' || resolvedId === 'sec-dashboard') {
                if (typeof renderDashboardComplete === 'function') renderDashboardComplete();
            } else if (resolvedId === 'escolas-panel') {
                if (typeof renderDbSchools === 'function') renderDbSchools();
            } else if (resolvedId === 'alunos-panel') {
                if (typeof renderDbStudents === 'function') renderDbStudents();
            } else if (resolvedId === 'metas-ideb') {
                if (typeof populateIdebGoalsTable === 'function') populateIdebGoalsTable();
            } else if (resolvedId === 'ideb-comparativo') {
                if (typeof initIdebCitySelector === 'function') initIdebCitySelector();
                if (typeof updateIdebComparativoView === 'function') updateIdebComparativoView();
            } else if (resolvedId === 'matriz-descritores') {
                if (typeof renderReferenceMatrix === 'function') renderReferenceMatrix();
                if (typeof renderBnccSkillsTable === 'function') renderBnccSkillsTable();
            } else if (resolvedId === 'cronograma-habilidades') {
                if (typeof render7ColCalendar === 'function') render7ColCalendar();
                if (typeof renderTeacherWeeklyChecklist === 'function') renderTeacherWeeklyChecklist();
            } else if (resolvedId === 'sec-criar-avaliacoes') {
                if (typeof populateWizardSchools === 'function') populateWizardSchools();
            } else if (resolvedId === 'sec-aplicacao-provas') {
                if (typeof renderEventsListForPrinting === 'function') renderEventsListForPrinting();
            } else if (resolvedId === 'banco-questoes') {
                if (typeof renderQuestions === 'function') renderQuestions();
            } else if (resolvedId === 'relatorios-monitoramento') {
                if (typeof renderAiGenDescriptors === 'function') renderAiGenDescriptors();
            } else if (resolvedId === 'gestao-pedagogica') {
                if (typeof renderPedagogicInterventions === 'function') renderPedagogicInterventions();
            } else if (resolvedId === 'biblioteca-recursos') {
                if (typeof renderPedagogicLibrary === 'function') renderPedagogicLibrary();
            } else if (resolvedId === 'admin-panel') {
                if (typeof loadUsersList === 'function') loadUsersList();
            }

            safeCreateIcons();
        } catch(e) {
            console.error('[Router Error]', e);
        }
    }

    window.switchTab = switchTab;
    window.switchMainTab = switchTab;
    window.showTab = switchTab;
    window.navigateToTab = switchTab;



